'use strict';
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
const sources = ['README.md','draft-summary.md','study/protocol.md','evidence/capture-notes.md','evidence/reference.csv','evidence/guide.csv','evidence/pairs.csv','guides/reference-card.txt','guides/reorganized-guide.txt','tools/check-evidence.cjs'];
const source_sha256 = Object.fromEntries(sources.map(p => [p,crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex')]));
function read(name) {
  const [header,...lines] = fs.readFileSync(path.join('evidence',name),'utf8').trim().split(/\\r?\\n/);
  const keys = header.split(',');
  const rows = lines.map(line => Object.fromEntries(line.split(',').map((v,i) => [keys[i],v])));
  const result = new Map(rows.map(r => [r.pair_id,r]));
  assert.equal(result.size,rows.length);
  return result;
}
const pairs = read('pairs.csv'), reference = read('reference.csv'), guide = read('guide.csv');
assert.deepEqual([...pairs.keys()].sort(),[...reference.keys()].sort());
assert.deepEqual([...pairs.keys()].sort(),[...guide.keys()].sort());
const rows = [...pairs].map(([pair_id,p]) => {
  const r=reference.get(pair_id),g=guide.get(pair_id);
  const rt=r.seconds === '' ? null : Number(r.seconds),gt=g.seconds === '' ? null : Number(g.seconds);
  const eligible=rt "'!== null && gt !== null && rt > 0 && gt > 0;
  return {...p,reference_seconds:rt,guide_seconds:gt,eligible,saved:eligible?rt-gt:null,reference_correct:r.correct==='"'true',guide_correct:g.correct==='true',reference_assisted:r.assisted==='true',guide_assisted:g.assisted==='true'};
});
const valid=rows.filter(r=>r.eligible);
const sum=(items,key)=>items.reduce((total,r)=>total+Number(r[key]),0);
const metrics={eligible_time_pairs:valid.length,reference_seconds:sum(valid,'reference_seconds'),guide_seconds:sum(valid,'guide_seconds'),time_saved_seconds:sum(valid,'saved'),faster_pairs:valid.filter(r=>r.saved>0).length,slower_pairs:valid.filter(r=>r.saved<0).length,tied_pairs:valid.filter(r=>r.saved===0).length,accuracy_pairs:rows.length,reference_correct:sum(rows,'reference_correct'),guide_correct:sum(rows,'guide_correct')};
const unassisted=valid.filter(r=>"'!r.reference_assisted&&!r.guide_assisted);
const order_groups=Object.fromEntries(['"'reference','guide'].map(format=>{
 const group=valid.filter(r=>r.first_format===format);
 return [format,{pairs:group.map(r=>r.pair_id),reference_seconds:sum(group,'reference_seconds'),guide_seconds:sum(group,'guide_seconds'),saved:sum(group,'saved')}];
}));
process.stdout.write(JSON.stringify({source_sha256,rows,metrics,saving_percent:100*metrics.time_saved_seconds/metrics.reference_seconds,unassisted_sensitivity:{pairs:unassisted.map(r=>r.pair_id),reference_seconds:sum(unassisted,'reference_seconds'),guide_seconds:sum(unassisted,'guide_seconds'),saved:sum(unassisted,'saved')},order_groups},null,2)+'\\n');
