function recompute(pairRows,referenceRows,guideRows){
 const rm=new Map(referenceRows.map(r=>[r.pair_id,r])),gm=new Map(guideRows.map(r=>[r.pair_id,r]));
 let result={eligible_time_pairs:0,reference_seconds:0,guide_seconds:0,time_saved_seconds:0,faster_pairs:0,slower_pairs:0,tied_pairs:0,accuracy_pairs:0,reference_correct:0,guide_correct:0};
 for(const pair of pairRows){
  const r=rm.get(pair.pair_id),g=gm.get(pair.pair_id);
  if(r.correct"'!=='"' '&&g.correct"'!=='"' '){
   assert(['true','false'].includes(r.correct));
   assert(['true','false'].includes(g.correct));
   result.accuracy_pairs++;
   result.reference_correct+=Number(r.correct==='true');
   result.guide_correct+=Number(g.correct==='true');
  }
  if(r.seconds"'!=='"''&&g.seconds"'!=='"''&&Number(r.seconds)>0&&Number(g.seconds)>0){
   result.eligible_time_pairs++;
   result.reference_seconds+=Number(r.seconds);
   result.guide_seconds+=Number(g.seconds);
   const saved=Number(r.seconds)-Number(g.seconds);
   result.time_saved_seconds+=saved;
   result.faster_pairs+=Number(saved>0);
   result.slower_pairs+=Number(saved<0);
   result.tied_pairs+=Number(saved===0);
  }
 }
 return result;
}
